CREATE DATABASE IF NOT EXISTS kasir_web CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE kasir_web;
DROP TABLE IF EXISTS detail_transaksi; DROP TABLE IF EXISTS transaksi; DROP TABLE IF EXISTS pelanggan; DROP TABLE IF EXISTS barang; DROP TABLE IF EXISTS users;
CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,nama_lengkap VARCHAR(100) NOT NULL,role ENUM("admin","kasir") DEFAULT "kasir",created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE barang(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,kode_barang VARCHAR(30) UNIQUE NOT NULL,nama_barang VARCHAR(100) NOT NULL,harga INT NOT NULL DEFAULT 0,stok INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE pelanggan(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nama VARCHAR(100) NOT NULL,no_hp VARCHAR(25),alamat TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE transaksi(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,kode_transaksi VARCHAR(40) UNIQUE NOT NULL,pelanggan_id INT UNSIGNED NULL,total INT NOT NULL DEFAULT 0,tanggal TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(pelanggan_id) REFERENCES pelanggan(id) ON DELETE SET NULL);
CREATE TABLE detail_transaksi(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,transaksi_id INT UNSIGNED NOT NULL,barang_id INT UNSIGNED NOT NULL,harga INT NOT NULL,jumlah INT NOT NULL,subtotal INT NOT NULL,FOREIGN KEY(transaksi_id) REFERENCES transaksi(id) ON DELETE CASCADE,FOREIGN KEY(barang_id) REFERENCES barang(id) ON DELETE RESTRICT);
